// Example of a reference cycle and its solution
struct Child;
struct Parent {
    std::shared_ptr<Child> child;
    ~Parent() { std::cout << "Parent destroyed\n"; }
};

struct Child {
    // std::shared_ptr<Parent> parent; // This creates a reference cycle!
    std::weak_ptr<Parent> parent; // This breaks the cycle
    ~Child() { std::cout << "Child destroyed\n"; }
};

// Demonstrate the cycle and the fix
auto p = std::make_shared<Parent>();
auto c = std::make_shared<Child>();

p->child = c;
c->parent = p; // With weak_ptr, this does NOT increase Parent's ref count

// When p and c go out of scope, the objects are now correctly deallocated.
// If Child held a shared_ptr, neither destructor would be called.

// Accessing through a weak_ptr
if (std::shared_ptr<Parent> locked_parent = c->parent.lock()) {
    // OK, parent is still alive. Use locked_parent here.
    std::cout << "Child can access its parent.\n";
} else {
    // Parent has been destroyed.
    std::cout << "Child's parent is gone.\n";
}
